class TermAndConSection extends StatelessWidget {
  const TermAndConSection({super.key});

  @override
  Widget build(BuildContext context) {
    final maxWidth = MediaQuery.of(context).size.width;

    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      TermAndConParagraph(
          header: "บทนำ",
          text:
              "ขอต้อนรับทุกท่านสู่ อีมาร์เก็ตเพลส ของธนาคารกรุงศรีอยุธยา จำกัด มหาชน (ต่อไปนี้เรียกว่า “กรุงศรี ออโต้”) สื่อกลางในการสั่งซื้อ ผลิตภัณฑ์และบริการ กรุณาอ่าน และปฏิบัติตามข้อกำหนดและเงื่อนไข การใช้งาน เพื่อประโยชน์ของตัวท่านเอง เพื่อให้เป็นไปตามกฎหมาย ท่านยืนยันว่าท่านมีอายุยี่สิบ (20) ปีขึ้นไป หากท่านมีอายุต่ำกว่ายี่สิบ (20) ปี ท่านรับทราบว่าท่านจะต้องได้รับอนุญาตจากบิดามารดาหรือ ผู้ปกครองของท่านในการใช้บริการของเรา และบิดามารดาหรือ ผู้ปกครองตามกฎหมายดังกล่าวต้องเห็นด้วยกับข้อกำหนดของ ข้อตกลงนี้ หากท่านไม่เข้าใจหรือมีข้อสงสัยความในข้อนี้ โปรดอย่าใช้ งานอีมาร์เก็ตเพลส จนกว่าจะได้ขอความช่วยเหลือหรือขอคำแนะนำ จากบิดามารดาหรือผู้ปกครองตามกฎหมายแล้ว หากท่านคือบิดา มารดาหรือผู้ปกครองตามกฎหมายของผู้เยาว์ที่กำลังใช้งาน ท่านจะ ต้องยอมรับข้อกำหนดของข้อตกลงนี้แทนผู้เยาว์และท่านจะต้อง รับผิดชอบต่อการใช้งานอีมาร์เก็ตเพลส ดังกล่าว"),
      TermAndConParagraph(
